import { test } from "node:test";
import assert from "node:assert/strict";
import { preorder, inorder, postorder, levelOrder } from "./attempt.js";

// Tiny tree builder: node(1, node(2), node(3)) → { value: 1, left: {...}, right: {...} }
function node(value, left = null, right = null) {
  return { value, left, right };
}

// A perfect tree of the given depth, numbered so an INORDER walk comes out
// as 1, 2, 3, ... — one assertion then covers the whole shape.
function perfect(depth) {
  let counter = 0;
  const build = (d) => {
    if (d === 0) return null;
    const left = build(d - 1);
    const value = ++counter;
    const right = build(d - 1);
    return node(value, left, right);
  };
  return build(depth);
}

//        1
//      /   \
//     2     3
//    / \   / \
//   4   5 6   7
const classic = () =>
  node(1, node(2, node(4), node(5)), node(3, node(6), node(7)));

const todo = [preorder, inorder, postorder, levelOrder].some((fn) =>
  fn.toString().includes("TODO")
);
const skip =
  todo && "unsolved — edit attempt.js (delete the TODO line) to activate these tests";

test("empty tree gives [] in all four orders", { skip }, () => {
  assert.deepEqual(preorder(null), []);
  assert.deepEqual(inorder(null), []);
  assert.deepEqual(postorder(null), []);
  assert.deepEqual(levelOrder(null), []);
});

test("a single node is the whole answer in all four orders", { skip }, () => {
  const tree = node(42);
  assert.deepEqual(preorder(tree), [42]);
  assert.deepEqual(inorder(tree), [42]);
  assert.deepEqual(postorder(tree), [42]);
  assert.deepEqual(levelOrder(tree), [42]);
});

test("preorder on the classic 7-node tree", { skip }, () => {
  assert.deepEqual(preorder(classic()), [1, 2, 4, 5, 3, 6, 7]);
});

test("inorder on the classic 7-node tree", { skip }, () => {
  assert.deepEqual(inorder(classic()), [4, 2, 5, 1, 6, 3, 7]);
});

test("postorder on the classic 7-node tree", { skip }, () => {
  assert.deepEqual(postorder(classic()), [4, 5, 2, 6, 7, 3, 1]);
});

test("levelOrder on the classic 7-node tree", { skip }, () => {
  assert.deepEqual(levelOrder(classic()), [1, 2, 3, 4, 5, 6, 7]);
});

test("a left-only chain", { skip }, () => {
  const tree = node(1, node(2, node(3, node(4))));
  assert.deepEqual(preorder(tree), [1, 2, 3, 4]);
  assert.deepEqual(inorder(tree), [4, 3, 2, 1]);
  assert.deepEqual(postorder(tree), [4, 3, 2, 1]);
  assert.deepEqual(levelOrder(tree), [1, 2, 3, 4]);
});

test("a right-only chain", { skip }, () => {
  const tree = node(1, null, node(2, null, node(3)));
  assert.deepEqual(preorder(tree), [1, 2, 3]);
  assert.deepEqual(inorder(tree), [1, 2, 3]);
  assert.deepEqual(postorder(tree), [3, 2, 1]);
  assert.deepEqual(levelOrder(tree), [1, 2, 3]);
});

test("nodes with just one child are not skipped", { skip }, () => {
  // 8 has a left child (7) and no right child.
  const tree = node(5, node(3, node(1), node(4)), node(8, node(7)));
  assert.deepEqual(preorder(tree), [5, 3, 1, 4, 8, 7]);
  assert.deepEqual(inorder(tree), [1, 3, 4, 5, 7, 8]);
  assert.deepEqual(postorder(tree), [1, 4, 3, 7, 8, 5]);
  assert.deepEqual(levelOrder(tree), [5, 3, 8, 1, 4, 7]);
});

test("duplicate values all survive", { skip }, () => {
  const tree = node(2, node(2, node(1)), node(2, null, node(1)));
  assert.deepEqual(preorder(tree), [2, 2, 1, 2, 1]);
  assert.deepEqual(inorder(tree), [1, 2, 2, 2, 1]);
  assert.deepEqual(postorder(tree), [1, 2, 1, 2, 2]);
  assert.deepEqual(levelOrder(tree), [2, 2, 2, 1, 1]);
});

test("the tree is not modified", { skip }, () => {
  const tree = classic();
  const snapshot = structuredClone(tree);
  preorder(tree);
  inorder(tree);
  postorder(tree);
  levelOrder(tree);
  assert.deepEqual(tree, snapshot);
});

test("a perfect 15-node tree", { skip }, () => {
  const tree = perfect(4);
  // inorder numbering means the inorder walk is just 1..15
  assert.deepEqual(inorder(tree), Array.from({ length: 15 }, (_, i) => i + 1));
  assert.deepEqual(preorder(tree), [8, 4, 2, 1, 3, 6, 5, 7, 12, 10, 9, 11, 14, 13, 15]);
  assert.deepEqual(postorder(tree), [1, 3, 2, 5, 7, 6, 4, 9, 11, 10, 13, 15, 14, 12, 8]);
  assert.deepEqual(levelOrder(tree), [8, 4, 12, 2, 6, 10, 14, 1, 3, 5, 7, 9, 11, 13, 15]);
});

test("a deep skewed tree does not lose nodes", { skip }, () => {
  // 400 nodes down the left spine: values 1..400 from the root down.
  let tree = null;
  for (let v = 400; v >= 1; v--) tree = node(v, tree);
  assert.equal(preorder(tree).length, 400);
  assert.deepEqual(preorder(tree).slice(0, 3), [1, 2, 3]);
  assert.deepEqual(inorder(tree).slice(0, 3), [400, 399, 398]);
  assert.deepEqual(levelOrder(tree).at(-1), 400);
});

/**
 * The four classic binary-tree traversals.
 *
 * Nodes are { value, left, right }; a missing child is null, and an empty
 * tree is null. Every function returns one flat array of values.
 *
 * The first three are depth-first (DFS) and are literally the same function:
 *
 *   preorder:   push, walk(left), walk(right)
 *   inorder:    walk(left), push, walk(right)
 *   postorder:  walk(left), walk(right), push
 *
 * The fourth is breadth-first (BFS) and needs a queue instead of recursion.
 *
 * Time  O(n) for all four: every node is pushed exactly once.
 * Space O(n) for the returned array, plus O(h) recursion stack for the DFS
 *       three (h = height) and O(w) queue for levelOrder (w = widest row).
 */

/**
 * Preorder: record a node BEFORE descending into either subtree.
 * "Copy this tree" and "print an outline" are preorder jobs — you need the
 * parent before you can attach the children.
 *
 * @param {object|null} root - the root node, or null for an empty tree
 * @returns {number[]} values in preorder
 */
export function preorder(root) {
  const out = [];

  const walk = (n) => {
    if (n === null) return; // base case: the empty tree contributes nothing
    out.push(n.value); // me...
    walk(n.left); // ...then everything on the left...
    walk(n.right); // ...then everything on the right
  };

  walk(root);
  return out;
}

/**
 * Inorder: record a node BETWEEN its two subtrees.
 * On a binary search tree (dsa/25) this comes out sorted — that is the
 * single most useful fact about inorder.
 *
 * @param {object|null} root - the root node, or null for an empty tree
 * @returns {number[]} values in inorder
 */
export function inorder(root) {
  const out = [];

  const walk = (n) => {
    if (n === null) return;
    walk(n.left); // everything smaller/left first...
    out.push(n.value); // ...then me...
    walk(n.right); // ...then everything right
  };

  walk(root);
  return out;
}

/**
 * Postorder: record a node AFTER both subtrees are done.
 * "Children first, then me" is the shape of every problem where a node's
 * answer depends on its children's answers — see dsa/26.
 *
 * @param {object|null} root - the root node, or null for an empty tree
 * @returns {number[]} values in postorder
 */
export function postorder(root) {
  const out = [];

  const walk = (n) => {
    if (n === null) return;
    walk(n.left);
    walk(n.right);
    out.push(n.value); // me last — the root is always the final element
  };

  walk(root);
  return out;
}

/**
 * Level order (breadth-first): the whole top row, then the next row down,
 * each row left to right. Recursion cannot do this — the call stack always
 * dives deep. A queue is what makes the walk go wide.
 *
 * @param {object|null} root - the root node, or null for an empty tree
 * @returns {number[]} values row by row, in one flat array
 */
export function levelOrder(root) {
  if (root === null) return [];

  const out = [];

  // A plain array used as a queue. `head` is the front of the line; we never
  // call shift(), because shift() re-indexes the whole array (O(n) each time,
  // O(n^2) overall). Moving an index instead is O(1) — the dsa/15 lesson.
  const queue = [root];
  let head = 0;

  while (head < queue.length) {
    const current = queue[head++]; // take the front of the line

    out.push(current.value);

    // Children join the BACK of the line, so the entire current row is
    // recorded before any of the next row is touched.
    if (current.left !== null) queue.push(current.left);
    if (current.right !== null) queue.push(current.right);
  }

  return out;
}

